import { Box, Button, Card, CardContent, Container, Stack, Typography } from "@mui/material";
import ArrowForwardIcon from "@mui/icons-material/ArrowForward";
import BlocksText from "../components/BlocksText";
import { mediaUrl } from "../services/api";
import type { HomeCourses } from "../types/home";

const BLUE = "#759ae1";
const NAVY = "#17224d";
const LIVE_SITE = "https://www.doctutorials.com";

function coursePageUrl(url?: string) {
  if (!url) return "";
  if (/^https?:\/\//i.test(url)) return url;
  if (url.startsWith("/")) return `${LIVE_SITE}${url}`;
  return `${LIVE_SITE}/${url}`;
}

export default function BestCourses({ data }: { data?: HomeCourses | null }) {
  if (!data) return null;

  return (
    <Box sx={{ py: { xs: 4, sm: 6, md: 8, lg: 10, tv: 12 } }}>
      <Container
        maxWidth={false}
        sx={{ px: { xs: 2, sm: 3, md: 5, tv: 8 }, maxWidth: { xs: "100%", md: "90%", tv: 1680 } }}
      >
        <Typography
          sx={{
            color: NAVY,
            fontSize: { xs: 22, sm: 26, md: 32, lg: 36, tv: 44 },
            fontWeight: 600,
            mb: 1,
            display: "flex",
            alignItems: "center",
            flexWrap: "wrap",
          }}
        >
          <Box
            component="span"
            sx={{
              width: { xs: 24, sm: 28, md: 36, tv: 44 },
              height: 3,
              backgroundColor: BLUE,
              display: "inline-block",
              mr: 0,
              flexShrink: 0,
            }}
          />
          {data.highlight ? (
            <>
              <Box component="span" sx={{ color: BLUE }}>
                {data.highlight}
              </Box>
              {data.title ? <Box component="span">&nbsp;{data.title}</Box> : null}
            </>
          ) : (
            data.title
          )}
        </Typography>
        <BlocksText content={data.description} sx={{ color: "#5a6473", mb: 5 }} />
        <Stack
          direction="row"
          flexWrap="wrap"
          useFlexGap
          sx={{ gap: { xs: 2.5, md: 8 } }}
          justifyContent="center"
        >
          {(data.items || []).map((course) => (
            <Card
              key={course.id || course.title}
              elevation={0}
              sx={{
                width: { xs: "100%", sm: 350 },
                display: "flex",
                flexDirection: "column",
                border: "none",
                boxShadow: "0 12px 22px -6px rgba(23, 34, 77, 0.14)",
                borderRadius: "16px",
                backgroundColor: "#fff",
                overflow: "hidden",
                clipPath: "inset(0 -32px -40px -32px)",
              }}
            >
              {mediaUrl(course.image) ? (
                <Box
                  component="img"
                  src={mediaUrl(course.image)}
                  alt={course.title}
                  sx={{
                    width: "100%",
                    height: 177,
                    objectFit: "cover",
                    display: "block",
                  }}
                />
              ) : null}
              <CardContent
                sx={{
                  display: "flex",
                  flexDirection: "column",
                  flex: 1,
                  pt: 2,
                  px: 2.5,
                  pb: 2.5,
                }}
              >
                <Typography sx={{ color: NAVY, fontWeight: 700, fontSize: 20, mb: 1 }}>
                  {course.title}
                </Typography>
                <BlocksText content={course.description} sx={{ color: "#5a6473", mb: 2 }} />
                <Box component="ul" sx={{ pl: 2.5, mb: 2, color: "#5a6473" }}>
                  {(course.features || []).map((item) => (
                    <Typography key={item.id || item.text} component="li" sx={{ mb: 0.5 }}>
                      {item.text}
                    </Typography>
                  ))}
                </Box>
                {course.exploreUrl ? (
                  <Button
                    href={coursePageUrl(course.exploreUrl)}
                    target="_blank"
                    rel="noopener noreferrer"
                    endIcon={<ArrowForwardIcon />}
                    sx={{
                      color: BLUE,
                      backgroundColor: "rgba(117, 154, 225, 0.16)",
                      mt: "auto",
                      alignSelf: "flex-start",
                      px: 1.75,
                      py: 0.75,
                      borderRadius: "8px",
                      boxShadow: "none",
                      "&:hover": {
                        backgroundColor: "rgba(117, 154, 225, 0.26)",
                        boxShadow: "none",
                      },
                    }}
                  >
                    Explore Course
                  </Button>
                ) : null}
              </CardContent>
            </Card>
          ))}
        </Stack>
      </Container>
    </Box>
  );
}
